import{_ as s,C as a,o as n,c as r,j as o,a as i,E as d,a2 as h}from"./chunks/framework.sc8Z_ZE3.js";const w=JSON.parse('{"title":"Session pool and handover","description":"","frontmatter":{},"headers":[],"relativePath":"work/session-pool.md","filePath":"work/session-pool.md"}'),l={name:"work/session-pool.md"};function p(c,e,u,v,f,k){const t=a("Badge");return n(),r("div",null,[e[0]||(e[0]=o("h1",{id:"session-pool-and-handover",tabindex:"-1"},[i("Session pool and handover "),o("a",{class:"header-anchor",href:"#session-pool-and-handover","aria-label":'Permalink to "Session pool and handover"'},"​")],-1)),d(t,{type:"built",text:"Built"}),e[1]||(e[1]=h(' Sessions live on the platform, so a thread is not tied to one machine. A person can hand a session to a colleague or put it into the Workspace&#39;s pool; whoever takes it over continues the same thread, and the workflow run that follows it, on their own device or on a <a href="/docs/install/runners">server runner</a>.<h2 id="hand-a-session-over" tabindex="-1">Hand a session over <a class="header-anchor" href="#hand-a-session-over" aria-label="Permalink to &quot;Hand a session over&quot;">​</a></h2><ul><li>In the chat: <strong>Hand over</strong> in the chat&#39;s header.</li><li>In the web companion: <strong>Hand over…</strong> in a job&#39;s detail.</li></ul><p>Choose who takes it over, a person or the <strong>session pool</strong> of the Workspace, and say why. The session keeps working until someone takes it.</p><h2 id="take-a-session-over" tabindex="-1">Take a session over <a class="header-anchor" href="#take-a-session-over" aria-label="Permalink to &quot;Take a session over&quot;">​</a></h2><p>The pool lists the sessions of your Workspaces that wait for someone. Members see what waits, without the transcript.</p><ul><li><strong>Web companion:</strong> the <strong>Pool</strong> tab, then <strong>Take over</strong>.</li><li><strong>Phone:</strong> under <strong>Needs you</strong>.</li></ul><p>The session, and its workflow run, continue on the same thread on the taker&#39;s device or runner. A seat entry, one that runs on a person&#39;s Claude or ChatGPT seat, goes only to a taker with a device that holds that engine and seat and can run it now; otherwise it is refused.</p><h2 id="session-files" tabindex="-1">Session files <a class="header-anchor" href="#session-files" aria-label="Permalink to &quot;Session files&quot;">​</a></h2><p>After each turn the launcher uploads the engine&#39;s session files (Claude Code&#39;s transcript, Codex&#39;s thread) to the platform, encrypted at rest, up to 50 MB. Only the device that runs the session&#39;s active turn can fetch them. So a thread survives its runner container and moves to another device or runner.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p><code>/api/v1/session-handovers</code>:</p><table tabindex="0"><thead><tr><th>Route</th><th>Does</th></tr></thead><tbody><tr><td><code>POST /api/v1/session-handovers</code></td><td>hand a session to a person or into the pool</td></tr><tr><td><code>GET /api/v1/session-handovers/pool</code></td><td>what waits in the pool</td></tr><tr><td><code>POST /api/v1/session-handovers/{id}/accept</code></td><td>take it over</td></tr><tr><td><code>POST /api/v1/session-handovers/{id}/decline</code></td><td>decline it</td></tr></tbody></table><p>An entry that is already resolved answers 409. These routes replace the run handover routes of 0.0.1-alpha.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>There is no pool page on the phone yet; the phone shows waiting sessions under <strong>Needs you</strong>.</li><li>A seat entry is refused to a taker without a device that can run it now.</li></ul><p>See also <a href="/docs/work/seat-takeover">Seat takeover</a>.</p>',19))])}const g=s(l,[["render",p]]);export{w as __pageData,g as default};
